int mystery(String s) {
if (s.isEmpty())
return 0;
char c = s.charAt(0);
s = s.substring(1);
if (Character.isUpperCase(c))
return 3 * mystery(s);
if (Character.isDigit(c))
return 5 + mystery(s);
if (c < 'l')
return -1 * mystery(s);
return 1 + 2 * mystery(s);
}

